var getAllOrderItems = async (order_id) => {
  const isExist = await prisma.orderItem.findFirst({
    where: {
      order_id
    }
  });
  if (!isExist) {
    return { status: 404 };
  }
  const allOrders = await prisma.orderItem.findMany({
    where: {
      order_id
    },
    include: {
      medicine: {
        select: {
          name: true
        }
      }
    }
  });
  const paidOrders = [];
  const deliveredOrders = [];
  const cancelledOrders = [];
  const generalOrders = [];
  for (const item of allOrders) {
    if (item.status === "DELIVERED" && item.price_paying_status === true) {
      paidOrders.push(item);
      continue;
    }
    if (item.status === "DELIVERED" && item.price_paying_status === false) {
      deliveredOrders.push(item);
      continue;
    }
    if (item.status === "CANCELLED") {
      cancelledOrders.push(item);
      continue;
    }
    generalOrders.push(item);
  }
  return {
    paidOrders,
    deliveredOrders,
    cancelledOrders,
    generalOrders,
    status: 200
  };
};
var getAllOrderItemForSeller = async (order_id, seller_id) => {
  const res = await prisma.orderItem.findMany({
    where: {
      order_id,
      seller_id
    },
    include: {
      medicine: {
        select: {
          name: true,
          img_url: true
        }
      }
    }
  });
  return res;
};
var cancelOrderItem = async (id, payLoad) => {
  const res = await prisma.$transaction(async (tx) => {
    const isExist = await tx.orderItem.findUnique({
      where: {
        id,
        status: payLoad.status
      },
      select: {
        medicine_id: true,
        order_id: true
      }
    });
    if (!isExist) {
      return { data: "Medicine Not Found", status: 404 };
    }
    await tx.orderItem.update({
      where: {
        id
      },
      data: {
        status: "CANCELLED"
      }
    });
    await tx.orders.update({
      where: {
        id: isExist?.order_id
      },
      data: {
        subtotal_amount: {
          decrement: Number(payLoad.price) * Number(payLoad.quantity)
        },
        total_amount: {
          decrement: Number(payLoad.price) * Number(payLoad.quantity)
        }
      }
    });
    await tx.medicines.update({
      where: {
        id: isExist.medicine_id
      },
      data: {
        stock: {
          increment: payLoad.quantity
        }
      }
    });
    return { data: "All is Ok", status: 200 };
  });
  return res;
};
var deliveredStatusChecking = async (order_id) => {
  const isExist = await prisma.orderItem.findFirst({
    where: {
      order_id,
      status: "DELIVERED"
    }
  });
  if (isExist) {
    return true;
  }
  return false;
};
var payOrderItem = async (id, payLoad) => {
  const res = await prisma.$transaction(async (tx) => {
    const isExist = await tx.orderItem.findUnique({
      where: {
        id,
        medicine_id: payLoad.medicine_id
      },
      select: {
        order_id: true
      }
    });
    if (!isExist) {
      return { data: "Medicine Not Found", status: 404 };
    }
    const isDeliverypaid = await tx.orders.findUnique({
      where: {
        id: isExist.order_id
      },
      select: {
        delivery_charge_status: true
      }
    });
    if (isDeliverypaid?.delivery_charge_status === false) {
      return { data: "Delivery Charge Not Paid Yet", status: 403 };
    }
    await tx.orderItem.update({
      where: {
        id
      },
      data: {
        price_paying_status: true
      }
    });
    const result = await tx.orders.update({
      where: {
        id: isExist.order_id
      },
      data: {
        total_paid_amount: {
          increment: Number(payLoad.quantity) * Number(payLoad.price)
        }
      }
    });
    return { data: result, status: 200 };
  });
  return res;
};
var getCountData = async (seller_id) => {
  const [paid_Orders, active_Orders] = await Promise.all([
    await prisma.orderItem.findMany({
      where: {
        seller_id,
        status: "DELIVERED",
        price_paying_status: true
      },
      select: {
        price: true,
        quantity: true
      }
    }),
    await prisma.orderItem.count({
      where: {
        seller_id,
        status: {
          in: ["PLACED", "PROCESSING"]
        }
      }
    })
  ]);
  const total_Revenue = paid_Orders.map((item) => Number(item.quantity) * Number(item.price)).reduce((acc, currentVal) => acc + currentVal, 0);
  return { total_Revenue, active_Orders };
};
var updateOrderItemStatus = async (id, payLoad) => {
  const res = await prisma.orderItem.update({
    where: {
      id
    },
    data: payLoad
  });
  return res;
};
